import{_ as i,a0 as s,w as a,s as u,ao as p,I as e,x as n,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"開源項目領導者可以如何營造包容的環境 | LCTT x X-CMD","titleTemplate":false,"description":"開源項目領導者可以如何營造包容的環境 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源項目領導者可以如何營造包容的環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源項目領導者可以如何營造包容的環境 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment","title":"開源項目領導者可以如何營造包容的環境","tag":"202304","desc":""},"relativePath":"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment.md","filePath":"[post].md"}'),d={name:"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment.md"};function m(f,t,x,T,v,b){const r=s("Link");return a(),u("div",null,[t[23]||(t[23]=p('<h1 id="開源項目領導者可以如何營造包容的環境" tabindex="-1">開源項目領導者可以如何營造包容的環境 <a class="header-anchor" href="#開源項目領導者可以如何營造包容的環境" aria-label="Permalink to “開源項目領導者可以如何營造包容的環境”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/22/234237shv6km5mua4tmb3v.jpg" alt=""></p><blockquote><p>那些被你領入社區的人，有一天也會向其他人伸出援手。</p></blockquote><p>開源領導者可以通過創造歸屬感、提供機會和表示支持來為新來者創造包容性社區。他們瞭解提交代碼和與其他社區成員建立聯繫的複雜性。創造包容性社區可以建立信譽並獲得影響力。這種經驗對於想要參與但不知道從哪裏開始的貢獻者來説是無價的。</p><p>幾年前，當我開始管理一個活躍於 Linux 內核社區的團隊時，我發現自己因為沒有任何內核經驗而感到處境困難。複雜的代碼庫、龐大的電子郵件歸檔和高風險的交流讓我感到害怕。當我團隊中的新內核開發人員表達了類似的感受時，我意識到我的感覺在團隊裏普遍存在。對於那些支持貢獻者或想自己做出貢獻的人來説，入門的道路並不總是清晰的，甚至可能感覺遙不可及。</p><h3 id="_4-個策略建立包容性領導力" tabindex="-1">4 個策略建立包容性領導力 <a class="header-anchor" href="#_4-個策略建立包容性領導力" aria-label="Permalink to “4 個策略建立包容性領導力”">​</a></h3>',6)),e("p",null,[t[2]||(t[2]=n("開源領導者可以通過為那些希望融入社區的人創造途徑來發揮自己的影響力。本文涵蓋的策略可應用於正式的 ",-1)),l(r,{href:"https://opensource.com/article/22/8/mentoring-power-multiplier"},{default:o(()=>[...t[0]||(t[0]=[n("指導",-1)])]),_:1}),t[3]||(t[3]=n(" 或 ",-1)),l(r,{href:"https://enterprisersproject.com/article/2021/4/it-leadership-how-to-coach?intcmp=7013a000002qLH8AAM"},{default:o(()=>[...t[1]||(t[1]=[n("輔導",-1)])]),_:1}),t[4]||(t[4]=n(" 關係，但同樣適用於日常互動。在培養環境的包容性時，看似微不足道的交流往往會產生最重要的影響。",-1))]),t[24]||(t[24]=e("h4",{id:"懷着好奇心接近了解新人",tabindex:"-1"},[n("懷着好奇心接近了解新人 "),e("a",{class:"header-anchor",href:"#懷着好奇心接近了解新人","aria-label":"Permalink to “懷着好奇心接近了解新人”"},"​")],-1)),t[25]||(t[25]=e("p",null,"經驗較少或來自非傳統背景的人可能會以意想不到或不同的方式解決問題。在應對這些差異時，如果用妄加評論或批評的方式，可能會在知識曲線通常很陡峭的社區中創造一個不安全的學習環境。例如，Linux 內核的長期貢獻者瞭解社區豐富的歷史，這意味着他們不需要明説就能理解社區的決策和反應。新的貢獻者必須積累這方面的知識，但只有當他們感到安全，並願意冒必要的風險來發展自己的技能時，他們才能有效地做到這一點。",-1)),t[26]||(t[26]=e("p",null,"開源領導者可以通過帶着好奇心去接近新人來支持他們學習。你可以問他們這樣的問題，“你能幫我理解一下你為什麼採用這種方法嗎？”而不是直接宣佈提議的解決方案“對或錯”。問題打開了一個繼續學習的對話，而不是關閉那些值得探索的重要方面的想法。這個過程也拓寬了領導者的視野，他們可以通過考慮新的觀點來學習。",-1)),t[27]||(t[27]=e("h4",{id:"發現並分享學習機會",tabindex:"-1"},[n("發現並分享學習機會 "),e("a",{class:"header-anchor",href:"#發現並分享學習機會","aria-label":"Permalink to “發現並分享學習機會”"},"​")],-1)),t[28]||(t[28]=e("p",null,"開源領導者可以確定適合其他人的項目，使他們可以獲得技術專長和學習社區流程。在為他人創造機會的同時，領導者也為自己創造了更多機會。這是因為他們有更多時間探索新的嘗試，同時通過分派任務繼續推進他們的工作。隨着領導者的成長，他們幫助周圍的人取得成功的能力變得與他們的直接貢獻一樣重要。",-1)),e("p",null,[t[6]||(t[6]=n("要知道 ",-1)),l(r,{href:"https://opensource.com/article/20/11/normalize-failure"},{default:o(()=>[...t[5]||(t[5]=[n("失敗",-1)])]),_:1}),t[7]||(t[7]=n(" 是學習的一部分，因此你要考慮找一些新手失敗後不會造成嚴重後果的項目。例如，在 Linux 內核中，代碼庫的某些部分的小改動可能會造成災難性的後果。考慮可以實現小小的勝利的項目，以幫助新來者在沒有高風險的情況下建立信心並感到掌控感。通過會議、電子郵件論壇或任何涉及如何參與到社區裏的宣傳活動分享這些想法，讓人們更容易獲取到這些信息。",-1))]),t[29]||(t[29]=e("h4",{id:"展現你脆弱的一面",tabindex:"-1"},[n("展現你脆弱的一面 "),e("a",{class:"header-anchor",href:"#展現你脆弱的一面","aria-label":"Permalink to “展現你脆弱的一面”"},"​")],-1)),t[30]||(t[30]=e("p",null,"擁有更多的經驗並不意味着你知道一切。通常情況下，即使是與我共事過的最有經驗的 Linux 內核貢獻者也會被未知子系統中的新挑戰擊敗。經驗不足的社區成員通常會認為經驗豐富的社區成員已經瞭解了一切。但是，經驗就是要善於找出你不知道的東西。如果你處於權威地位或者被認為是專家，你可以通過分享個人掙扎和堅持的經驗來表現你脆弱的一面，這樣做可以鼓勵那些和你有着類似感受的人。",-1)),t[31]||(t[31]=e("h4",{id:"為他人做擔保",tabindex:"-1"},[n("為他人做擔保 "),e("a",{class:"header-anchor",href:"#為他人做擔保","aria-label":"Permalink to “為他人做擔保”"},"​")],-1)),t[32]||(t[32]=e("p",null,"向你的人脈介紹新來的成員。在激發他們興趣的領域裏，讓新成員和在這個領域內具有專業知識的社區成員建立聯繫。在公共論壇上説出他們的名字，並稱贊他們所做的出色工作。作為受人尊敬的領導者，你的支持可以幫助他們在社區內建立聯繫和信任。",-1)),t[33]||(t[33]=e("p",null,"通過樹立社區包容性，我們可以擁有豐富多樣的社區。我希望開源領導者會考慮這些建議，因為你提拔到社區的人未來的某天也會同樣向別人伸出援手。",-1)),t[34]||(t[34]=e("p",null,[e("em",null,"（題圖：MJ:inclusive environment community illustration in high resolution, very detailed）")],-1)),t[35]||(t[35]=e("hr",null,null,-1)),e("p",null,[t[9]||(t[9]=n("via: ",-1)),l(r,{href:"https://opensource.com/article/23/2/open-source-leaders-inclusive-environment"},{default:o(()=>[...t[8]||(t[8]=[n("https://opensource.com/article/23/2/open-source-leaders-inclusive-environment",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("作者：",-1)),l(r,{href:"https://opensource.com/users/kcarcia"},{default:o(()=>[...t[10]||(t[10]=[n("Kate Carcia Poulin",-1)])]),_:1}),t[15]||(t[15]=n(" 選題：",-1)),l(r,{href:"https://github.com/lkxed"},{default:o(()=>[...t[11]||(t[11]=[n("lkxed",-1)])]),_:1}),t[16]||(t[16]=n(" 譯者：",-1)),l(r,{href:"https://github.com/XiaotingHuang22"},{default:o(()=>[...t[12]||(t[12]=[n("XiaotingHuang22",-1)])]),_:1}),t[17]||(t[17]=n(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=n("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原創編譯，",-1)),l(r,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中國",-1)])]),_:1}),t[22]||(t[22]=n(" 榮譽推出",-1))])])}const L=i(d,[["render",m]]);export{k as __pageData,L as default};
